window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-44cea4aba6802a59"]={"versions": [{"id": "FIG-44cea4aba6802a59", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Speichermodell- / Endianness-Mapping-Diagramm (Hardware-zu-Logik-Abbildungsdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Definition der byteweisen Serialisierung und Speicherabbildung eines skalaren 16-Bit-Ganzzahldatenworts im Speicher für Little-Endian-Zielarchitekturen gemäß AUTOSAR-Konvention <code>LOW_BYTE_FIRST</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Verortung in <code>Platform_Types</code> (<code>AUTOSAR_SWS_PlatformTypes</code>) als hardwareabstrahierende Spezifikationsgrundlage für den Basic Software (BSW) Stack, Compiler-Abstraktion und Treiberentwicklung (MCAL) im AUTOSAR Classic Core.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Domänen-Einteilung (Trennlinie gestrichelt):</strong>\n<ul class=\"fig-list\"><li><strong>Information (Logische Ebene):</strong>\n<ul class=\"fig-list\"><li>16-Bit Datenelement (<code>16 bit width</code>, z. B. <code>uint16</code>, <code>sint16</code>).\n</li><li><strong>LS Byte (<code>Byte0</code>):</strong> Least Significant Byte (Bits 0–7 des logischen Werts).\n</li><li><strong>MS Byte (<code>Byte1</code>):</strong> Most Significant Byte (Bits 8–15 des logischen Werts).\n</li></ul>\n</li><li><strong>Hardware (Physikalische Ebene):</strong>\n<ul class=\"fig-list\"><li>Byte-adressierbarer Speicher (<code>Memory</code>).\n</li><li>Basisadresse <code>Address n</code>: Niederwertigste Speicheradresse des Datenworts.\n</li><li>Folgeadresse <code>Address n+1</code>: Nächsthöhere Speicheradresse.\n</li></ul>\n</li></ul>\n</li><li><strong>Relationen &amp; Adress-Mapping:</strong>\n<ul class=\"fig-list\"><li>Value[7:0] → Address n\n</li><li>Value[15:8] → Address n+1\n</li><li>Der niederwertigste Byte-Anteil (<code>LS Byte</code>) belegt stets die niedrigere Speicheradresse (<code>LOW_BYTE_FIRST</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (Statisches Struktur- und Repräsentationsmodell):</strong> Kein Protokollablauf, Zustandsautomat oder asynchroner Kommunikationspfad.\n</li><li><strong>Zugriffssemantik im RAM/Register:</strong>\n<ul class=\"fig-list\"><li>Byte-Zugriff auf <code>Address n</code> liefert direkt das Least Significant Byte (<code>Byte0</code>).\n</li><li>Wort-Lese- bzw. Schreibzugriffe des Prozessorkerns interpretieren die Byte-Sequenz <code>[Address n, Address n+1]</code> ohne Software-Swapping direkt als nativen Wert <code>(Byte1 &lt;&lt; 8) | Byte0</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Referenz:</strong>\n<ul class=\"fig-list\"><li><strong>[SWS_Platform_00051]:</strong> Spezifikation des Präprozessor-Makros <code>CPU_BYTE_ORDER</code> in <code>Platform_Types.h</code>. Für Plattformen gemäß dieser Abbildung zwingend zu definieren als:\n<pre class=\"fig-pre\"><code>#define CPU_BYTE_ORDER LOW_BYTE_FIRST</code></pre>\n</li></ul>\n</li><li><strong>Auswirkungen auf BSW- und MCAL-Entwickler:</strong>\n<ul class=\"fig-list\"><li><strong>Com-Stack &amp; PDU-Serialisierung (PduR / Com / CanTp):</strong> Signal-Extraktion aus Kommunikations-PDUs muss das Verhältnis zwischen <code>CPU_BYTE_ORDER</code> und der konfigurierten Signal-Endianness (z. B. <code>COM_BUS_LITTLE_ENDIAN</code> vs. <code>COM_BUS_BIG_ENDIAN</code>) abgleichen. Bei <code>LOW_BYTE_FIRST</code>-Hosts ist für Little-Endian-Signale kein Byte-Swapping erforderlich.\n</li><li><strong>Treiber- &amp; Speicherzugriffe (DMA / Fls / Fee / NvM):</strong> Blocktransfers über byteweise arbeitende Peripherie/Hardware (DMA-Kanäle, Flash-Treiber) behalten die Speicherreihenfolge n → Byte0, n+1 → Byte1 bei.\n</li><li><strong>Portabilität:</strong> Vermeidung von plattformabhängigen Union-Overlays oder unaligned Byte-Pointer-Casts auf Multi-Byte-Typen in portablem SWC- und BSW-Code, da dies bei Wechsel auf Architekturen mit <code>HIGH_BYTE_FIRST</code> (<code>CPU_BYTE_ORDER == 1</code>) zu Fehlinterpretationen führt.\n</li></ul>\n</li></ul>"}, {"id": "FIG-977419331874710b", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Speichermodell- / Endianness-Mapping-Diagramm (Hardware-zu-Logik-Abbildungsdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Definition der byteweisen Serialisierung und Speicherabbildung eines skalaren 16-Bit-Ganzzahldatenworts im Speicher für Little-Endian-Zielarchitekturen gemäß AUTOSAR-Konvention <code>LOW_BYTE_FIRST</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Verortung in <code>Platform_Types</code> (<code>AUTOSAR_SWS_PlatformTypes</code>) als hardwareabstrahierende Spezifikationsgrundlage für den Basic Software (BSW) Stack, Compiler-Abstraktion und Treiberentwicklung (MCAL) im AUTOSAR Classic Core.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Domänen-Einteilung (Trennlinie gestrichelt):</strong>\n<ul class=\"fig-list\"><li><strong>Information (Logische Ebene):</strong>\n<ul class=\"fig-list\"><li>16-Bit Datenelement (<code>16 bit width</code>, z. B. <code>uint16</code>, <code>sint16</code>).\n</li><li><strong>LS Byte (<code>Byte0</code>):</strong> Least Significant Byte (Bits 0–7 des logischen Werts).\n</li><li><strong>MS Byte (<code>Byte1</code>):</strong> Most Significant Byte (Bits 8–15 des logischen Werts).\n</li></ul>\n</li><li><strong>Hardware (Physikalische Ebene):</strong>\n<ul class=\"fig-list\"><li>Byte-adressierbarer Speicher (<code>Memory</code>).\n</li><li>Basisadresse <code>Address n</code>: Niederwertigste Speicheradresse des Datenworts.\n</li><li>Folgeadresse <code>Address n+1</code>: Nächsthöhere Speicheradresse.\n</li></ul>\n</li></ul>\n</li><li><strong>Relationen &amp; Adress-Mapping:</strong>\n<ul class=\"fig-list\"><li>Value[7:0] → Address n\n</li><li>Value[15:8] → Address n+1\n</li><li>Der niederwertigste Byte-Anteil (<code>LS Byte</code>) belegt stets die niedrigere Speicheradresse (<code>LOW_BYTE_FIRST</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (Statisches Struktur- und Repräsentationsmodell):</strong> Kein Protokollablauf, Zustandsautomat oder asynchroner Kommunikationspfad.\n</li><li><strong>Zugriffssemantik im RAM/Register:</strong>\n<ul class=\"fig-list\"><li>Byte-Zugriff auf <code>Address n</code> liefert direkt das Least Significant Byte (<code>Byte0</code>).\n</li><li>Wort-Lese- bzw. Schreibzugriffe des Prozessorkerns interpretieren die Byte-Sequenz <code>[Address n, Address n+1]</code> ohne Software-Swapping direkt als nativen Wert <code>(Byte1 &lt;&lt; 8) | Byte0</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Referenz:</strong>\n<ul class=\"fig-list\"><li><strong>[SWS_Platform_00051]:</strong> Spezifikation des Präprozessor-Makros <code>CPU_BYTE_ORDER</code> in <code>Platform_Types.h</code>. Für Plattformen gemäß dieser Abbildung zwingend zu definieren als:\n<pre class=\"fig-pre\"><code>#define CPU_BYTE_ORDER LOW_BYTE_FIRST</code></pre>\n</li></ul>\n</li><li><strong>Auswirkungen auf BSW- und MCAL-Entwickler:</strong>\n<ul class=\"fig-list\"><li><strong>Com-Stack &amp; PDU-Serialisierung (PduR / Com / CanTp):</strong> Signal-Extraktion aus Kommunikations-PDUs muss das Verhältnis zwischen <code>CPU_BYTE_ORDER</code> und der konfigurierten Signal-Endianness (z. B. <code>COM_BUS_LITTLE_ENDIAN</code> vs. <code>COM_BUS_BIG_ENDIAN</code>) abgleichen. Bei <code>LOW_BYTE_FIRST</code>-Hosts ist für Little-Endian-Signale kein Byte-Swapping erforderlich.\n</li><li><strong>Treiber- &amp; Speicherzugriffe (DMA / Fls / Fee / NvM):</strong> Blocktransfers über byteweise arbeitende Peripherie/Hardware (DMA-Kanäle, Flash-Treiber) behalten die Speicherreihenfolge n → Byte0, n+1 → Byte1 bei.\n</li><li><strong>Portabilität:</strong> Vermeidung von plattformabhängigen Union-Overlays oder unaligned Byte-Pointer-Casts auf Multi-Byte-Typen in portablem SWC- und BSW-Code, da dies bei Wechsel auf Architekturen mit <code>HIGH_BYTE_FIRST</code> (<code>CPU_BYTE_ORDER == 1</code>) zu Fehlinterpretationen führt.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-44cea4aba6802a59", "to": "FIG-977419331874710b", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
